/**
 * Unit tests for ArrayRealVector.getLInfNorm().
 * 
 * Note: The implementation provided in the prompt:
 * max += Math.max(max, Math.abs(a));
 * is mathematically unusual for an L-infinity norm (which should be max(|a_i|)).
 * This implementation actually calculates a cumulative sum of maximums.
 * The tests below are written to validate the behavior of the PROVIDED code.
 */
public class ArrayRealVector_getLInfNorm_TriageGen0Test {

    @Test
    public void testGetLInfNorm_EmptyVector() {
        ArrayRealVector vector = new ArrayRealVector(new double[]{});
        // max starts at 0, loop doesn't execute
        Assert.assertEquals(0.0, vector.getLInfNorm(), 1e-10);
    }
















}

